<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {useRoute} from 'vue-router';
import {api,apiBlob} from '../core/http';
import {useAccountStore} from '../stores/account';
import AppHeader from '../components/AppHeader.vue';
import AppState from '../components/AppState.vue';
import AppBottomSheet from '../components/AppBottomSheet.vue';
import {requirePrivacyReview} from '../services/privacyGuard';
const uploadConsent=ref(false);

const route=useRoute(),account=useAccountStore();
const items=ref<any[]>([]),cases=ref<any[]>([]),tasks=ref<any[]>([]),loading=ref(false),working=ref(false),error=ref(''),message=ref('');
const q=ref(''),category=ref(''),formOpen=ref(false),editingId=ref(''),file=ref<File|null>(null);
const form=ref<any>({name:'',category:'other',case_id:'',task_id:''});
const preview=ref<any>(null),previewOpen=ref(false);
const categoryLabels:Record<string,string>={form:'表单',proof:'证明材料',certificate:'证书',transcript:'成绩材料',identity:'身份材料',reference:'参考资料',other:'其他'};
const formTitle=computed(()=>editingId.value?'编辑材料':'上传材料');

onMounted(loadInitial);onUnmounted(clearPreview);
async function loadInitial(){if(!account.signedIn)return;loading.value=true;error.value='';try{cases.value=await api('/api/v1/cases?limit=100');const requested=String(route.query.case||'');if(requested&&cases.value.some(item=>item.id===requested))form.value.case_id=requested;await load()}catch(e:any){error.value=e?.message||'材料库读取失败'}finally{loading.value=false}}
async function load(){if(!account.signedIn)return;loading.value=true;error.value='';try{const params=new URLSearchParams();if(q.value.trim())params.set('q',q.value.trim());if(category.value)params.set('category',category.value);items.value=await api('/api/v1/vault/items?'+params.toString())}catch(e:any){error.value=e?.message||'材料列表读取失败'}finally{loading.value=false}}
async function loadTasks(caseId:string){tasks.value=[];if(!caseId)return;try{tasks.value=(await api(`/api/v1/cases/${caseId}/plan`)).ordered_tasks||[]}catch(e:any){error.value=e?.message||'事项步骤读取失败'}}
async function changeCase(){form.value.task_id='';await loadTasks(form.value.case_id)}
function openUpload(){editingId.value='';file.value=null;uploadConsent.value=false;form.value={name:'',category:'other',case_id:String(route.query.case||''),task_id:''};loadTasks(form.value.case_id);formOpen.value=true;error.value='';message.value=''}
async function openEdit(item:any){editingId.value=item.id;file.value=null;form.value={name:item.name,category:item.category,case_id:item.case_ids?.[0]||'',task_id:item.task_ids?.[0]||''};await loadTasks(form.value.case_id);formOpen.value=true;error.value='';message.value=''}
function choose(event:Event){uploadConsent.value=false;file.value=(event.target as HTMLInputElement).files?.[0]||null;if(file.value&&!form.value.name)form.value.name=file.value.name}
async function save(){working.value=true;error.value='';message.value='';try{const case_ids=form.value.case_id?[form.value.case_id]:[],task_ids=form.value.task_id?[form.value.task_id]:[];if(editingId.value){await api('/api/v1/vault/items/'+editingId.value,{method:'PATCH',body:JSON.stringify({name:form.value.name.trim(),category:form.value.category,case_ids,task_ids})})}else{if(!file.value)throw Error('请选择要上传的文件');const guard=await requirePrivacyReview('',[file.value],'',uploadConsent.value);if(guard.unchecked_sources.length&&!window.confirm('文件未端侧识别，请人工核对隐私并确认上传。'))return;const body=new FormData();body.append('file',file.value);body.append('consent','true');body.append('name',form.value.name.trim()||file.value.name);body.append('category',form.value.category);body.append('case_ids',JSON.stringify(case_ids));body.append('task_ids',JSON.stringify(task_ids));await api('/api/v1/vault/items',{method:'POST',body})}formOpen.value=false;message.value=editingId.value?'材料信息已更新。':'材料已上传。';await load()}catch(e:any){error.value=e?.message||'材料保存失败'}finally{working.value=false}}
async function remove(item:any){if(!window.confirm(`删除“${item.name}”？`))return;working.value=true;try{await api('/api/v1/vault/items/'+item.id,{method:'DELETE'});message.value='材料已删除。';if(editingId.value===item.id)formOpen.value=false;await load()}catch(e:any){error.value=e?.message||'删除失败'}finally{working.value=false}}
function clearPreview(){if(preview.value?.url)URL.revokeObjectURL(preview.value.url);preview.value=null}
async function view(item:any){working.value=true;error.value='';clearPreview();try{const blob=await apiBlob(item.content_url);const value:any={name:item.name,mime:item.mime,url:URL.createObjectURL(blob),text:''};if(item.mime.startsWith('text/'))value.text=await blob.text();preview.value=value;previewOpen.value=true}catch(e:any){error.value=e?.message||'材料内容读取失败'}finally{working.value=false}}
function closePreview(){previewOpen.value=false;clearPreview()}
function caseName(id:string){return cases.value.find(item=>item.id===id)?.title||id}
function sizeLabel(size:number){if(size<1024)return `${size} B`;if(size<1024*1024)return `${(size/1024).toFixed(1)} KB`;return `${(size/1024/1024).toFixed(1)} MB`}
</script>

<template><div class="page page--utility page--vault"><AppHeader title="材料库"><template #action><button v-if="account.signedIn" class="button button--small button--primary" type="button" @click="openUpload">上传</button></template></AppHeader><div v-if="error" class="notice notice--danger">{{error}}</div><div v-if="message" class="notice notice--success">{{message}}</div><AppState v-if="!account.signedIn" title="登录后管理材料" description="上传内容和关联关系会按账户隔离保存。"><RouterLink class="button button--primary" to="/auth/login">登录</RouterLink></AppState><template v-else><form class="vault-filters" @submit.prevent="load"><input v-model="q" type="search" placeholder="搜索材料名称"><select v-model="category" @change="load"><option value="">全部分类</option><option v-for="(label,value) in categoryLabels" :key="value" :value="value">{{label}}</option></select><button class="button button--small button--secondary">搜索</button></form><AppState v-if="loading" kind="loading" title="正在读取材料"/><AppState v-else-if="!items.length" title="还没有符合条件的材料" description="上传文件后，可以关联到具体事项和步骤。"><button class="button button--primary" type="button" @click="openUpload">上传第一份材料</button></AppState><div v-else class="vault-grid"><article v-for="item in items" :key="item.id" class="surface-card vault-card"><div class="vault-card__top"><span class="vault-file-icon"><img src="/assets/icons/files/file_other.svg" alt=""></span><div><h3>{{item.name}}</h3><p>{{categoryLabels[item.category]||item.category}} · {{sizeLabel(item.size)}}</p></div></div><div v-if="item.case_ids?.length" class="vault-links"><span v-for="caseId in item.case_ids" :key="caseId">{{caseName(caseId)}}</span><small v-if="item.task_ids?.length">关联 {{item.task_ids.length}} 个步骤</small></div><div class="vault-card__actions"><button class="button button--small button--secondary" type="button" :disabled="working" @click="view(item)">查看</button><button class="button button--small button--secondary" type="button" @click="openEdit(item)">编辑</button><button class="button button--small button--danger" type="button" :disabled="working" @click="remove(item)">删除</button></div></article></div></template><AppBottomSheet :open="formOpen" :title="formTitle" @close="formOpen=false"><form class="form-card vault-form" @submit.prevent="save"><label v-if="!editingId" class="file-picker"><input type="file" @change="choose"><span><b>{{file?.name||'选择文件'}}</b><small>单个文件不超过 20 MB</small></span></label><label>材料名称<input v-model="form.name" required maxlength="255"></label><label>分类<select v-model="form.category"><option v-for="(label,value) in categoryLabels" :key="value" :value="value">{{label}}</option></select></label><label>关联事项<select v-model="form.case_id" @change="changeCase"><option value="">不关联事项</option><option v-for="item in cases" :key="item.id" :value="item.id">{{item.title}}</option></select></label><label>关联步骤<select v-model="form.task_id" :disabled="!form.case_id"><option value="">不关联步骤</option><option v-for="task in tasks" :key="task.id" :value="task.id">{{task.title}}</option></select></label><label v-if="!editingId" class="consent-row"><input v-model="uploadConsent" type="checkbox">我已核对材料隐私并同意上传到当前账户；图片等未完成端侧扫描。</label><button class="button button--primary button--block" :disabled="working||(!editingId&&!uploadConsent)">{{working?'保存中…':editingId?'保存修改':'上传并保存'}}</button></form></AppBottomSheet><AppBottomSheet :open="previewOpen" :title="preview?.name||'查看材料'" @close="closePreview"><div v-if="preview" class="vault-preview"><pre v-if="preview.text">{{preview.text}}</pre><img v-else-if="preview.mime.startsWith('image/')" :src="preview.url" :alt="preview.name"><iframe v-else-if="preview.mime==='application/pdf'" :src="preview.url" :title="preview.name"></iframe><p v-else>此格式请下载后查看。</p><a class="button button--primary button--block" :href="preview.url" :download="preview.name">下载文件</a></div></AppBottomSheet></div></template>
